// tb_nlp_small - small Spikformer NLP integer chain replay (M2 gate).
//
// Case: E32 / H1 / HD32 / seq4 / T2 / MLP64 / depth2 / V64, full frozen top
// stream ABI (tables -> tokens -> per-block 4 descriptor + weight beats ->
// block in/out beats -> o_sums/o_sums_valid/o_done), TWO consecutive samples
// with no global reset, two blocks with clearly different weights/thresholds.
//
// Golden: build/spikformer/nlp_48h_20261029_1915/replay/case_small/
//         (generated by scripts/spikformer/gen_nlp_small.py; cross-checked
//          bit-exactly against tools/backends/spikformer/integer_ref.py)
// Driver: scripts/spikformer/run_nlp_sim.py --case small
//
// Checks: every embed beat, every block input beat and every block output beat
// (data/order/count/last), o_sums per channel, o_sums_valid/o_done level
// semantics (exactly one assertion per sample), deterministic input bubbles,
// X checks, transaction-budget watchdog (timeout => FAIL with state dump).
// Beat checks use the frozen hierarchical monitor names
// (contract hardware_abi.hierarchical_monitor_names): u_emb / u_blk.
`timescale 1ns/1ps
module tb_nlp_small;
  // ---- frozen case parameters (must match gen_nlp_common.CASE_CFG['small']) ----
  localparam int E = 32;
  localparam int HEADS = 1;
  localparam int HD = 32;
  localparam int HIDDEN = 64;
  localparam int T = 2;
  localparam int NTOK = 4;
  localparam int DEPTH = 2;
  localparam int TL = 8;
  localparam int TC = 8;
  localparam int RW = 4;
  localparam int PSUM_SLICE = 32;
  localparam int SUM_W = 6;
  localparam int LANES = 8;
  localparam int VTAB = 64;
  localparam int OW = 32;
  localparam int NS = 2;                       // consecutive samples, no global reset
  localparam int G = E / TL;                   // block groups per token
  localparam int EB = E / LANES;               // embed groups per token
  localparam int NB = NTOK * G;                // block in/out beats per block
  localparam int NBE = NTOK * EB;              // embed beats per sample
  localparam int IW = TL * T * RW;             // block I/O beat width
  localparam int EW = LANES * T;               // embed beat width
  localparam int NW = 4 * E * E / 8 + 4 * E / 2 + HIDDEN * E / 8 + HIDDEN / 2
                     + E * HIDDEN / 8 + E / 2; // weight beats per block
  localparam int NSTREAM = 4 + NW;             // descriptor + weight beats per block
  localparam int TS0 = VTAB * E / 8;           // etab beats
  localparam int TS1 = NTOK * E / 8;           // ptab beats
  localparam int TBL = TS0 + TS1;
  // transaction budget: ~2556 external beats/sample * 3 (bubbles) + small compute;
  // 200k cycles is a hard bound, never treated as data.
  localparam longint WATCHDOG = 200000;

  reg s_clk = 0;
  reg s_rst = 1;
  reg i_start = 0;
  wire o_done;
  reg [63:0] i_tab_data = 0;
  reg i_tab_valid = 0;
  wire o_tab_ready;
  reg [15:0] i_tok_id = 0;
  reg i_tok_valid = 0;
  wire o_tok_ready;
  reg [63:0] i_w_data = 0;
  reg i_w_valid = 0;
  wire o_w_ready;
  wire [OW-1:0] o_sums [E];
  wire o_sums_valid;

  always #5 s_clk = ~s_clk;

  spikformer_nlp_top #(
    .E(E), .HEADS(HEADS), .HEAD_DIM(HD), .HIDDEN(HIDDEN), .T(T), .TOKENS(NTOK),
    .DEPTH(DEPTH), .TL(TL), .TC(TC), .RW(RW), .PSUM_SLICE(PSUM_SLICE),
    .SUM_W(SUM_W), .LANES(LANES), .VTAB(VTAB), .OW(OW)
  ) dut (
    .s_clk(s_clk), .s_rst(s_rst), .i_start(i_start), .o_done(o_done),
    .i_tab_data(i_tab_data), .i_tab_valid(i_tab_valid), .o_tab_ready(o_tab_ready),
    .i_tok_id(i_tok_id), .i_tok_valid(i_tok_valid), .o_tok_ready(o_tok_ready),
    .i_w_data(i_w_data), .i_w_valid(i_w_valid), .o_w_ready(o_w_ready),
    .o_sums(o_sums), .o_sums_valid(o_sums_valid)
  );

  // ---- expected vectors (loaded from +VECDIR) ----
  reg [63:0] tab_words [0:TBL-1];
  reg [63:0] stream [0:NS*DEPTH*NSTREAM-1];
  reg [15:0] toks [0:NS*NTOK-1];
  reg [EW-1:0] exp_emb [0:NS*NBE-1];
  reg [IW-1:0] exp_in [0:NS*DEPTH*NB-1];
  reg [IW-1:0] exp_out [0:NS*DEPTH*NB-1];
  reg [OW-1:0] exp_sums [0:NS*E-1];

  // ---- driver / monitor state ----
  integer cur_s = 0;
  integer in_cnt = 0;      // global block input beats (order: sample, block, beat)
  integer out_cnt = 0;     // global block output beats
  integer emb_cnt = 0;     // global embed beats
  integer cyc = 0;
  bit armed [0:NS-1];
  bit sums_cap [0:NS-1];
  bit done_cap [0:NS-1];
  bit failed = 0;
  bit allow_mm = 0;      // debug: +NLP_ALLMISMATCH keeps collecting after a beat mismatch
  integer mm_cnt = 0;
  bit trace_on = 0;      // +NLP_TRACE: dump key block-internal boundaries for first-mismatch localisation
  bit blk_done_prev = 0;
  integer n, c, tt;
  integer last_out_cyc = -1;
  integer done_cyc [0:NS-1];
  integer i, s, b;
  string vecdir;

  task automatic tb_fail(input string msg);
    begin
      failed = 1;
      $display("NLP_FAIL case=small cycle=%0d sample=%0d %s", cyc, cur_s, msg);
      $display("  state: in_cnt=%0d/%0d out_cnt=%0d/%0d emb_cnt=%0d/%0d done=%b sums_valid=%b",
               in_cnt, NS*DEPTH*NB, out_cnt, NS*DEPTH*NB, emb_cnt, NS*NBE,
               o_done, o_sums_valid);
      $display("NLP_RESULT case=small pass=0 cycles=%0d", cyc);
      $finish;
    end
  endtask

  // ---- first-mismatch context helpers (frozen port data only, no internals) ----
  function automatic string lane_vals(input [IW-1:0] d);
    string r;
    integer l2, t2;
    begin
      r = "";
      for (l2 = 0; l2 < TL; l2 = l2 + 1) begin
        if (l2 != 0) r = {r, "/"};
        for (t2 = 0; t2 < T; t2 = t2 + 1)
          r = {r, $sformatf("%0d", d[(l2*T+t2+1)*RW-1 -: RW])};
      end
      lane_vals = r;
    end
  endfunction

  function automatic string emb_vals(input [EW-1:0] d);
    string r;
    integer l2, t2;
    begin
      r = "";
      for (l2 = 0; l2 < LANES; l2 = l2 + 1) begin
        if (l2 != 0) r = {r, "/"};
        for (t2 = 0; t2 < T; t2 = t2 + 1)
          r = {r, $sformatf("%0d", d[l2*T+t2])};
      end
      emb_vals = r;
    end
  endfunction

  // ---- watchdog: a timeout is a FAIL with a state dump, never data ----
  initial begin
    forever begin
      @(posedge s_clk);
      if (!s_rst) begin
        cyc = cyc + 1;
        if (cyc > WATCHDOG) begin
          $display("NLP_FAIL case=small WATCHDOG timeout after %0d cycles (transaction budget exceeded)", cyc);
          $display("  state: sample=%0d in_cnt=%0d out_cnt=%0d emb_cnt=%0d start=%b done=%b tab_rdy=%b tok_rdy=%b w_rdy=%b sums_valid=%b",
                   cur_s, in_cnt, out_cnt, emb_cnt, i_start, o_done, o_tab_ready,
                   o_tok_ready, o_w_ready, o_sums_valid);
          $display("  block: in_valid=%b in_ready=%b out_valid=%b out_ready=%b out_last=%b",
                   dut.u_blk.i_in_valid, dut.u_blk.o_in_ready, dut.u_blk.o_out_valid,
                   dut.u_blk.i_out_ready, dut.u_blk.o_out_last);
          $display("NLP_RESULT case=small pass=0 cycles=%0d", cyc);
          $finish;
        end
      end
    end
  end

  // ---- monotonic beat / sums / done monitor: sample at posedge (pre-edge values decide) ----
  always @(posedge s_clk) begin
    if (!s_rst && !failed) begin
      // embed output beats (u_emb frozen monitor name)
      if (dut.u_emb.o_beat_valid === 1'b1 && dut.u_emb.i_beat_ready === 1'b1) begin
        if (emb_cnt >= NS*NBE)
          tb_fail("extra embed beat");
        else if (dut.u_emb.o_beat_data !== exp_emb[emb_cnt])
          tb_fail($sformatf("embed beat %0d data mismatch got=%h[%s] want=%h[%s]",
                            emb_cnt, dut.u_emb.o_beat_data,
                            emb_vals(dut.u_emb.o_beat_data), exp_emb[emb_cnt],
                            emb_vals(exp_emb[emb_cnt])));
        else begin
          emb_cnt = emb_cnt + 1;
          if (dut.u_emb.o_beat_last !== (((emb_cnt % NBE) == 0) ? 1'b1 : 1'b0))
            tb_fail($sformatf("embed beat %0d last flag %b", emb_cnt - 1,
                              dut.u_emb.o_beat_last));
        end
      end
      // block input beats (u_blk frozen monitor names)
      if (dut.u_blk.i_in_valid === 1'b1 && dut.u_blk.o_in_ready === 1'b1) begin
        if (in_cnt >= NS*DEPTH*NB)
          tb_fail("extra block input beat");
        else if (dut.u_blk.i_in_data !== exp_in[in_cnt])
          tb_fail($sformatf("block-in beat %0d data mismatch got=%h[%s] want=%h[%s]",
                            in_cnt, dut.u_blk.i_in_data,
                            lane_vals(dut.u_blk.i_in_data), exp_in[in_cnt],
                            lane_vals(exp_in[in_cnt])));
        else
          in_cnt = in_cnt + 1;
      end
      // block output beats
      if (dut.u_blk.o_out_valid === 1'b1 && dut.u_blk.i_out_ready === 1'b1) begin
        if (out_cnt >= NS*DEPTH*NB)
          tb_fail("extra block output beat");
        else if (dut.u_blk.o_out_data !== exp_out[out_cnt]) begin
          if (allow_mm) begin
            mm_cnt = mm_cnt + 1;
            $display("NLP_MM block-out beat=%0d cycle=%0d got=%h[%s] want=%h[%s]",
                       out_cnt, cyc, dut.u_blk.o_out_data,
                       lane_vals(dut.u_blk.o_out_data), exp_out[out_cnt],
                       lane_vals(exp_out[out_cnt]));
            last_out_cyc = cyc;
            out_cnt = out_cnt + 1;
          end else
            tb_fail($sformatf("block-out beat %0d data mismatch got=%h[%s] want=%h[%s]",
                              out_cnt, dut.u_blk.o_out_data,
                              lane_vals(dut.u_blk.o_out_data), exp_out[out_cnt],
                              lane_vals(exp_out[out_cnt])));
        end else if (dut.u_blk.o_out_last !== (((out_cnt % NB) == NB-1) ? 1'b1 : 1'b0))
          tb_fail($sformatf("block-out beat %0d o_out_last=%b", out_cnt,
                            dut.u_blk.o_out_last));
        else begin
          last_out_cyc = cyc;
          out_cnt = out_cnt + 1;
        end
      end
      // bounded progress trace (frozen port-level info only; default off)
      if (trace_on && !failed) begin
        if (dut.u_blk.o_done === 1'b1 && !blk_done_prev)
          $display("NLP_TR block_done sample=%0d block=%0d cycle=%0d out_beats=%0d",
                   cur_s, ((out_cnt - cur_s*DEPTH*NB) / NB) - 1, cyc, out_cnt);
        blk_done_prev = (dut.u_blk.o_done === 1'b1);
      end
      // o_sums (level until next i_start; exactly one assertion per sample)
      if (cur_s < NS && armed[cur_s]) begin
        if (o_sums_valid === 1'b1 && !sums_cap[cur_s]) begin
          sums_cap[cur_s] = 1;
          if (out_cnt != (cur_s+1)*DEPTH*NB)
            tb_fail($sformatf("o_sums_valid before all block-out beats (out_cnt=%0d)", out_cnt));
          for (i = 0; i < E; i = i + 1) begin
            if (o_sums[i] !== exp_sums[cur_s*E + i]) begin
              if (allow_mm) begin
                mm_cnt = mm_cnt + 1;
                $display("NLP_MM o_sums[%0d] got=%h want=%h", i, o_sums[i],
                         exp_sums[cur_s*E + i]);
              end else
                tb_fail($sformatf("o_sums[%0d] mismatch got=%h want=%h",
                                  i, o_sums[i], exp_sums[cur_s*E + i]));
            end
          end
        end
        if (o_done === 1'b1 && !done_cap[cur_s]) begin
          done_cap[cur_s] = 1;
          done_cyc[cur_s] = cyc;
          if (out_cnt != (cur_s+1)*DEPTH*NB)
            tb_fail($sformatf("o_done before all block-out beats (out_cnt=%0d)", out_cnt));
          if (!sums_cap[cur_s])
            tb_fail("o_done without o_sums_valid");
          if (cyc <= last_out_cyc)
            tb_fail("o_done asserted before final output beat accepted");
        end
      end
    end
  end

  // ---- external-stream handshake drivers (payload stable while stalled) ----
  task automatic send_tab(input [63:0] d, input integer idx);
    begin
      @(negedge s_clk);
      i_tab_data = d; i_tab_valid = 1;
      while (o_tab_ready !== 1'b1) @(negedge s_clk);
      @(posedge s_clk);
      @(negedge s_clk);
      i_tab_valid = 0;
      if ((idx % 7) == 3) @(negedge s_clk);           // deterministic input bubble
      if ((idx % 13) == 11) begin @(negedge s_clk); @(negedge s_clk); end
    end
  endtask

  task automatic send_tok(input [15:0] d, input integer idx);
    begin
      @(negedge s_clk);
      i_tok_id = d; i_tok_valid = 1;
      while (o_tok_ready !== 1'b1) @(negedge s_clk);
      @(posedge s_clk);
      @(negedge s_clk);
      i_tok_valid = 0;
      if ((idx % 3) == 1) @(negedge s_clk);
    end
  endtask

  task automatic send_w(input [63:0] d, input integer idx);
    begin
      @(negedge s_clk);
      i_w_data = d; i_w_valid = 1;
      while (o_w_ready !== 1'b1) @(negedge s_clk);
      @(posedge s_clk);
      @(negedge s_clk);
      i_w_valid = 0;
      if ((idx % 5) == 2) @(negedge s_clk);
      if ((idx % 11) == 7) begin @(negedge s_clk); @(negedge s_clk); end
    end
  endtask

  task automatic pulse_start();
    begin
      @(negedge s_clk);
      i_start = 1;
      @(posedge s_clk);
      @(negedge s_clk);
      i_start = 0;
    end
  endtask

  // ---- load vectors, run both samples, report PASS/FAIL ----
  initial begin
    allow_mm = $test$plusargs("NLP_ALLMISMATCH");
    trace_on = $test$plusargs("NLP_TRACE");
    if (!$value$plusargs("VECDIR=%s", vecdir)) begin
      $display("NLP_FAIL case=small missing +VECDIR plusarg");
      $display("NLP_RESULT case=small pass=0 cycles=0");
      $finish;
    end
    $readmemh($sformatf("%s/etab.hex", vecdir), tab_words, 0, TS0-1);
    $readmemh($sformatf("%s/ptab.hex", vecdir), tab_words, TS0, TBL-1);
    for (s = 0; s < NS; s = s + 1) begin
      $readmemh($sformatf("%s/toks_s%0d.hex", vecdir, s), toks, s*NTOK, (s+1)*NTOK-1);
      $readmemh($sformatf("%s/exp_emb_s%0d.hex", vecdir, s), exp_emb, s*NBE, (s+1)*NBE-1);
      $readmemh($sformatf("%s/exp_sums_s%0d.hex", vecdir, s), exp_sums, s*E, (s+1)*E-1);
      for (b = 0; b < DEPTH; b = b + 1) begin
        $readmemh($sformatf("%s/stream_b%0d_s%0d.hex", vecdir, b, s), stream,
                  (s*DEPTH+b)*NSTREAM, (s*DEPTH+b+1)*NSTREAM-1);
        $readmemh($sformatf("%s/exp_in_b%0d_s%0d.hex", vecdir, b, s), exp_in,
                  s*DEPTH*NB + b*NB, s*DEPTH*NB + (b+1)*NB-1);
        $readmemh($sformatf("%s/exp_out_b%0d_s%0d.hex", vecdir, b, s), exp_out,
                  s*DEPTH*NB + b*NB, s*DEPTH*NB + (b+1)*NB-1);
      end
    end
    $display("NLP_TB case=small E=%0d H=%0d T=%0d N=%0d depth=%0d MLP=%0d V=%0d",
             E, HEADS, T, NTOK, DEPTH, HIDDEN, VTAB);
    $display("NLP_TB golden dir=%s watchdog=%0d cycles", vecdir, WATCHDOG);
    repeat (4) @(posedge s_clk);
    s_rst = 0;
    repeat (2) @(posedge s_clk);

    for (s = 0; s < NS; s = s + 1) begin
      cur_s = s;
      armed[s] = 0;
      sums_cap[s] = 0;
      done_cap[s] = 0;
      in_cnt = s*DEPTH*NB;        // global counters continue across samples
      out_cnt = s*DEPTH*NB;
      emb_cnt = s*NBE;
      pulse_start();
      repeat (2) @(negedge s_clk);
      if (o_done !== 1'b0 || o_sums_valid !== 1'b0)
        tb_fail($sformatf("sample %0d: o_done/o_sums_valid not cleared by i_start (done=%b sums_valid=%b)",
                          s, o_done, o_sums_valid));
      armed[s] = 1;
      $display("NLP_SAMPLE %0d start cycle=%0d tokens=%0d %0d %0d %0d", s, cyc,
               toks[s*NTOK], toks[s*NTOK+1], toks[s*NTOK+2], toks[s*NTOK+3]);
      for (i = 0; i < TBL; i = i + 1) send_tab(tab_words[i], i);
      for (i = 0; i < NTOK; i = i + 1) send_tok(toks[s*NTOK+i], i);
      for (b = 0; b < DEPTH; b = b + 1)
        for (i = 0; i < NSTREAM; i = i + 1)
          send_w(stream[(s*DEPTH+b)*NSTREAM + i], i);
      wait (sums_cap[s] && done_cap[s]);
      if (emb_cnt != (s+1)*NBE)
        tb_fail($sformatf("sample %0d embed beat count %0d != %0d", s, emb_cnt, (s+1)*NBE));
      if (in_cnt != (s+1)*DEPTH*NB)
        tb_fail($sformatf("sample %0d block-in count %0d != %0d", s, in_cnt, (s+1)*DEPTH*NB));
      if (out_cnt != (s+1)*DEPTH*NB)
        tb_fail($sformatf("sample %0d block-out count %0d != %0d", s, out_cnt, (s+1)*DEPTH*NB));
      $display("NLP_SAMPLE %0d done cycle=%0d out_beats=%0d in_beats=%0d emb_beats=%0d",
               s, cyc, out_cnt, in_cnt, emb_cnt);
    end
    if (!failed) begin
      $display("NLP_PASS case=small samples=%0d beats_per_block=%0d sums=%0d mismatches=%0d", NS, NB, E, mm_cnt);
      $display("NLP_RESULT case=small pass=1 cycles=%0d", cyc);
    end
    $finish;
  end
endmodule